"use client";

/**
 * Flag rows with a switch each.
 *
 * Owner D. Private to the flags route. The switch is only offered for
 * `overridable` flags; the rest are shown read-only with the reason they are on
 * or off, which is more useful than a disabled control with no explanation.
 */

import { useTransition } from "react";
import type { FeatureFlagKey } from "@/types/feature-flag";

export type FlagRow = {
  readonly key: FeatureFlagKey;
  readonly label: string;
  readonly description: string;
  readonly strategy: string;
  readonly overridable: boolean;
  readonly overridden: boolean;
  readonly enabled: boolean;
};

export type FlagToggleListProps = {
  rows: readonly FlagRow[];
  onToggle: (flag: FeatureFlagKey, enabled: boolean) => void;
};

export function FlagToggleList(props: FlagToggleListProps) {
  const [pending, startTransition] = useTransition();

  return (
    <ul className="divide-y divide-slate-200 rounded-md border border-slate-200 bg-white">
      {props.rows.map((row) => (
        <li key={row.key} className="flex items-start gap-4 px-4 py-4">
          <div className="min-w-0 flex-1">
            <p className="text-sm font-medium">{row.label}</p>
            <p className="mt-0.5 text-sm text-slate-600">{row.description}</p>
            <p className="mt-1 text-xs text-slate-400">
              {row.strategy}
              {row.overridden ? " · overridden for this organization" : ""}
            </p>
          </div>

          {row.overridable ? (
            <label className="flex items-center gap-2 text-sm">
              <input
                type="checkbox"
                checked={row.enabled}
                disabled={pending}
                onChange={(event) => {
                  const next = event.target.checked;
                  startTransition(() => {
                    props.onToggle(row.key, next);
                  });
                }}
              />
              {row.enabled ? "On" : "Off"}
            </label>
          ) : (
            <span className="text-xs uppercase tracking-wide text-slate-400">
              {row.enabled ? "On" : "Off"}
            </span>
          )}
        </li>
      ))}
    </ul>
  );
}

"use server";

/**
 * Updates org profile and settings.
 *
 * Owner D. `settings` is a partial patch — the service merges it over the
 * stored `OrganizationSettings` so a form that only touches `digestHourUtc`
 * cannot silently clear the flag overrides.
 *
 * Must call (do not reimplement): updateOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  updateOrganizationSchema,
  type UpdateOrganizationInput,
} from "@/schemas/organization";
import { updateOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

const run = withAction<typeof updateOrganizationSchema, Organization>(
  updateOrganizationSchema,
  async (raw, actor) => {
    const input = raw as UpdateOrganizationInput;

    if (!can(actor, "org:update", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:update");
    }

    const organization = await updateOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function updateOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
import { z } from "zod";
